Here's an example JavaScript function that takes an array of five numbers as input and checks if any of them are valid prime numbers:

```javascript
function checkPrimes(numbers) {
  for (let I = 0; I < numbers.length; i++) {
    let currentNum = numbers[i];
    if (isPrime(currentNum)) {
      console.log(`The ${currentNum} is a prime!`);
      return;
    }
  }
}

function isPrime(num) {
  if (num <= 2) {
    return true; // 1 and 2 are prime
  }

  for (let I = Math.sqrt(num); I > 2; i--) {
    if (num % I === 0) {
      return false; // if num is divisible by anything other than 1 or itself, it's not prime
    }
  }
  return true; // if no factors were found, the number is prime
}
```

To use this function with your array of numbers, you can simply call `checkPrimes([...yourArray])`. Make sure that `isPrime` exists somewhere within whatever scope you're using the function in.

Note: The `Math.sqrt` method finds the square root of a given number. It's used here to speed up the primes check by starting the iteration at the square root of the number rather than going all the way down to 2.

